const genreGroup=button('+ Genres group',()=>change(()=>{const g=makeGroup('Genres');g.branches=genres.movie.map(([id,title])=>({id:crypto.randomUUID(),title,enabled:true,sources:[makeBranch(`${title} movies`,'DISCOVER','movie',{withGenres:id}).source]}));draft.rows.push(g);selected=expanded=g.id;nav=[];},'Genres Branch Group added.'),'chip');genreGroup.title='Branch Group · Movies by genre';$('preset-list').append(genreGroup);
for(const b of document.querySelectorAll('.home-scope [data-close]'))b.addEventListener('click',()=>$(b.dataset.close).close());
render();
/** What creator.js uses: picks from the catalog, the profile photo and change notifications. */
export const home={
 pickState:item=>pickState(draft,item),
 /** Adds a setup or group. Returns "added", "replaced", "included", "duplicate" or "full". */
 add(item,title){if(previewItem?.item.id===item.id)previewItem=null;const state=pickState(draft,item);if(state!=='available')return state==='added'?'duplicate':state;let status;change(()=>{status=addPick(draft,item,title);if(status==='added'||status==='replaced')selected=`pick.${item.id}`;});return status;},
 avatar:()=>draft.avatar||null,
 setAvatar(path){change(()=>{draft.avatar=path;});},
 badgePack:()=>draft.badgePack||null,
 /** A source-badge pack by its `badge-packs/` file name. */
 setBadgePack(id){change(()=>{draft.badgePack=id;});},
 counts:()=>counts(draft),
 /** Shows a setup or group on the preview without adding it; null stops. quiet keeps the page where it is. */
 preview(item,title,{quiet=false}={}){previewItem=item?{item,title:title||item.id}:null;screen='home';nav=[];renderPreview();for(const f of listeners)f();if(item){$('home-preview').scrollTop=0;if(!quiet&&innerWidth<900)$('panel-home').scrollIntoView({block:'start',behavior:'smooth'});}},
 previewing:()=>previewItem?.item.id||null,
 /** Switches the preview to Home, a title page ("title") or Who's watching ("who"). */
 showScreen(name){if(['home','title','who'].includes(name)){screen=name;renderPreview();}},
 onChange(f){listeners.add(f);},
 /** Lookups from the loaded catalog, so picks show their covers and current titles. */
 connect(hooks){({describePick=describePick,describeAvatar=describeAvatar,describeBadgePack=describeBadgePack,badgeImages=badgeImages,openSetup=openSetup,showTab=showTab}=hooks);for(const r of draft.rows)if(r.kind==='pick'){const t=describePick(r.item)?.title;if(t)r.title=t;}render();},
};
